def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Fast outcome counting
    cc = cd = dc = dd = 0
    for mine, opp in history:
        if mine == 'C':
            if opp == 'C':
                cc += 1
            else:
                cd += 1
        else:
            if opp == 'C':
                dc += 1
            else:
                dd += 1

    last_mine, last_opp = history[-1]

    # Consecutive opponent defections
    opp_run_d = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_run_d += 1
        else:
            break

    # Consecutive opponent cooperations
    opp_run_c = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'C':
            opp_run_c += 1
        else:
            break

    # Consecutive mutual defection
    dd_run = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D' and history[i][1] == 'D':
            dd_run += 1
        else:
            break

    opp_c = cc + dc
    opp_d = cd + dd
    coop_rate = opp_c / float(n)

    # Strongly cooperative opponent: preserve mutual cooperation
    if coop_rate >= 0.85 and opp_run_d == 0:
        # Rare gentle probe, but avoid jeopardizing long CC runs
        if n % 29 == 0 and rng.random() < 0.05:
            return 'D'
        return 'C'

    # Very exploitative opponent: defend, with occasional repair attempts
    if coop_rate <= 0.2:
        if opp_run_d >= 4 and rng.random() < 0.08:
            return 'C'
        return 'D'

    # Long mutual defection cycle: try to break out
    if dd_run >= 2:
        if rng.random() < 0.45:
            return 'C'
        return 'D'

    # Opponent defected last
    if last_opp == 'D':
        # If we defected last too and they just cooperated before, mirror considerations
        if opp_run_d == 1:
            # Single defection: retaliate once, but forgive soon
            if last_mine == 'C':
                # Defected after our cooperation. Short punishment.
                return 'D'
            else:
                # We both defected once; offer repair
                if rng.random() < 0.6:
                    return 'C'
                return 'D'
        # Multiple consecutive defections: punish, with occasional olive branch
        if opp_run_d == 2:
            if rng.random() < 0.25:
                return 'C'
            return 'D'
        # Long defection streak: mostly defect, rare probe
        if rng.random() < 0.08:
            return 'C'
        return 'D'

    # Opponent cooperated last
    if last_opp == 'C':
        # If we defected last and they cooperated, reward with cooperation
        if last_mine == 'D':
            # Count how often we've defected while they cooperated
            if dc >= 3 and coop_rate > 0.7:
                # We've been exploiting; return to cooperation generously
                return 'C'
            return 'C'
        # If we're in mutual cooperation, maintain it
        if opp_run_c >= 1 and last_mine == 'C':
            # Very rare late-game check instead of mid-game noise
            if n >= 95 and coop_rate > 0.7:
                # Last few rounds: gentle probing only if opponent already defects some
                if opp_d >= 3 and rng.random() < 0.1:
                    return 'D'
            return 'C'
        return 'C'

    return 'C'
